using System.ComponentModel.DataAnnotations;using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace MediStock.Pages.Suppliers;
[Authorize]public sealed class CreateModel(MediStockDbContext db):PageModel{[BindProperty]public SupplierInput Input{get;set;}=new();public async Task<IActionResult>OnPostAsync(CancellationToken ct){if(!ModelState.IsValid)return Page();db.Suppliers.Add(new Supplier{Name=Input.Name.Trim(),ContactPerson=Clean(Input.ContactPerson),Phone=Input.Phone.Trim(),Email=Clean(Input.Email),Address=Clean(Input.Address),IsActive=true,CreatedUtc=DateTime.UtcNow});await db.SaveChangesAsync(ct);TempData["StatusMessage"]="Supplier added.";return RedirectToPage("Index");}private static string?Clean(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();}
public sealed class SupplierInput{[Required,StringLength(160)]public string Name{get;set;}="";[StringLength(160)]public string?ContactPerson{get;set;}[Required,Phone,StringLength(30)]public string Phone{get;set;}="";[EmailAddress,StringLength(254)]public string?Email{get;set;}[StringLength(500)]public string?Address{get;set;}}
